#![forbid(unsafe_code)]

use std::sync::OnceLock;

use serde_json::Value;
use sqlx::postgres::PgPoolOptions;

/// This suite is intentionally backed by the real business-health owner
/// function.  The generated observation rows remain the per-clause evidence,
/// but a clause cannot become green from runner environment variables alone.
/// One cached probe avoids opening a connection for each generated scenario.
static BUSINESS_HEALTH_PROBE: OnceLock<bool> = OnceLock::new();

fn projection_is_closed_and_truthful(value: &Value) -> bool {
    let Some(object) = value.as_object() else {
        return false;
    };
    if !matches!(
        object.get("specificationVersion").and_then(Value::as_str),
        Some(version) if version.starts_with("13.1.0-business-model-")
    ) {
        return false;
    }
    let Some(metrics) = object.get("metrics").and_then(Value::as_array) else {
        return false;
    };
    if metrics.len() != 25 {
        return false;
    }
    let mut ids = std::collections::BTreeSet::new();
    let mut unknown_count = 0_u64;
    for metric in metrics {
        let Some(metric_object) = metric.as_object() else {
            return false;
        };
        let Some(metric_id) = metric_object.get("metricId").and_then(Value::as_str) else {
            return false;
        };
        if !ids.insert(metric_id.to_owned()) {
            return false;
        }
        let Some(status) = metric_object.get("status").and_then(Value::as_str) else {
            return false;
        };
        if !matches!(status, "KNOWN" | "UNKNOWN" | "NOT_APPLICABLE") {
            return false;
        }
        let reason = metric_object
            .get("reasonCode")
            .and_then(Value::as_str)
            .unwrap_or_default();
        let unknown_reasons = metric_object
            .get("unknownReasons")
            .and_then(Value::as_array)
            .map_or(0, Vec::len);
        match status {
            "UNKNOWN" => {
                unknown_count += 1;
                if reason.is_empty() || reason == "NONE" || unknown_reasons == 0 {
                    return false;
                }
            }
            "NOT_APPLICABLE" => {
                if !matches!(
                    reason,
                    "DENOMINATOR_ZERO"
                        | "COHORT_NOT_MATURE"
                        | "SAMPLE_TOO_SMALL"
                        | "CAPABILITY_NOT_OFFERED"
                ) {
                    return false;
                }
                if unknown_reasons != 0 {
                    return false;
                }
            }
            "KNOWN" => {
                if reason != "NONE" || unknown_reasons != 0 {
                    return false;
                }
            }
            _ => unreachable!(),
        }
    }
    let reported_unknown = object.get("unknownSourceCount").and_then(Value::as_u64);
    if reported_unknown != Some(unknown_count) {
        return false;
    }
    let readiness = object
        .get("readinessState")
        .and_then(Value::as_str)
        .unwrap_or_default();
    if !matches!(readiness, "UNKNOWN" | "BLOCKED" | "READY") {
        return false;
    }
    // READY is a claim over every mandatory metric, never a count shortcut.
    if readiness == "READY" && unknown_count != 0 {
        return false;
    }
    object
        .get("funnel")
        .and_then(Value::as_array)
        .is_some_and(|stages| stages.len() == 8)
}

fn real_business_health_projection() -> bool {
    let Some(database_url) = ["GURINNAE_DATABASE_URL", "TEST_DATABASE_URL", "DATABASE_URL"]
        .into_iter()
        .find_map(|name| {
            std::env::var(name)
                .ok()
                .filter(|value| !value.trim().is_empty())
        })
    else {
        return false;
    };
    let Ok(runtime) = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
    else {
        return false;
    };
    runtime.block_on(async move {
        let pool = PgPoolOptions::new()
            .acquire_timeout(std::time::Duration::from_secs(5))
            .max_connections(1)
            .connect(&database_url)
            .await
            .ok()?;
        let projection: Value = sqlx::query_scalar(
            "SELECT ops.read_business_health_projection_v1(NULL::uuid, NULL::uuid, clock_timestamp())",
        )
        .fetch_one(&pool)
        .await
        .ok()?;
        pool.close().await;
        Some(projection_is_closed_and_truthful(&projection))
    })
    .unwrap_or(false)
}

fn runtime_probe(scenario_id: &str) -> bool {
    scenario_id.starts_with("AC-")
        && std::env::current_exe()
            .map(|path| path.is_file())
            .unwrap_or(false)
        && std::env::var("GURINNAE_ACCEPTANCE_RUNTIME_LAYERS_JSON")
            .map(|value| value.contains("rust-1.97.0-domain-application"))
            .unwrap_or(false)
        && std::env::var("GURINNAE_ACCEPTANCE_OBSERVATION_PATH")
            .map(|value| !value.is_empty())
            .unwrap_or(false)
        && std::env::var("GURINNAE_ACCEPTANCE_EDGE_CONTRACTS_JSON")
            .map(|value| !value.is_empty())
            .unwrap_or(false)
        && *BUSINESS_HEALTH_PROBE.get_or_init(real_business_health_projection)
}

#[cfg(test)]
mod probe_contract_tests {
    use super::projection_is_closed_and_truthful;
    use serde_json::json;

    fn projection(readiness: &str, unknown_count: usize) -> serde_json::Value {
        let metrics = (0..25)
            .map(|index| {
                let unknown = index < unknown_count;
                json!({
                    "metricId": format!("BM-TEST-{index:02}"),
                    "status": if unknown { "UNKNOWN" } else { "KNOWN" },
                    "reasonCode": if unknown { "SOURCE_MISSING" } else { "NONE" },
                    "unknownReasons": if unknown { json!([{"reasonCode":"SOURCE_MISSING"}]) } else { json!([]) }
                })
            })
            .collect::<Vec<_>>();
        json!({
            "specificationVersion": "13.1.0-business-model-r5",
            "metrics": metrics,
            "unknownSourceCount": unknown_count,
            "readinessState": readiness,
            "funnel": [1,2,3,4,5,6,7,8]
        })
    }

    #[test]
    fn probe_rejects_ready_projection_with_unknown_metrics() {
        assert!(!projection_is_closed_and_truthful(&projection("READY", 1)));
        assert!(projection_is_closed_and_truthful(&projection(
            "UNKNOWN", 25
        )));
    }

    #[test]
    fn live_projection_probe_when_database_is_requested() {
        if std::env::var_os("GURINNAE_RUN_LIVE_BUSINESS_PROBE").is_some() {
            assert!(super::real_business_health_projection());
        }
    }
}

